const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // 1. Geometry & Time Definitions
  const cairns = ee.Geometry.Point(145.7710, -16.9205);
  const cooktown = ee.Geometry.Point(145.248920, -15.475923);
  const dateRange = ['2025-01-31', '2025-02-05']; // End date exclusive

  // 2. Data Acquisition - Try CHIRPS for rainfall
  let dataset = 'UCSB-CHG/CHIRPS/DAILY';
  let col = ee.ImageCollection(dataset)
    .filterDate(dateRange[0], dateRange[1])
    .select('precipitation');

  // Check data availability
  const count = col.size().getInfo();
  if (count === 0) {
    print("CHIRPS collection empty - trying GPM");
    // Try GPM as fallback
    dataset = 'NASA/GPM_L3/IMERG_V06';
    col = ee.ImageCollection(dataset)
      .filterDate(dateRange[0], dateRange[1])
      .select('precipitationCal');

    const gpmCount = col.size().getInfo();
    if (gpmCount === 0) {
      print("No rainfall data for 2025 period");
      print("<answer>C1</answer>");
      return;
    }
    print(`GPM Images: ${gpmCount}`);
  } else {
    print(`CHIRPS Images: ${count}`);
  }

  // 3. Processing - Sum rainfall over period
  const rainfallTotal = col.sum();

  // Extract values at both locations
  const cairnsRain = rainfallTotal.reduceRegion({
    reducer: ee.Reducer.sum(),
    geometry: cairns,
    scale: 1000,
    maxPixels: 1e9
  }).get('precipitation' || 'precipitationCal');

  const cooktownRain = rainfallTotal.reduceRegion({
    reducer: ee.Reducer.sum(),
    geometry: cooktown,
    scale: 1000,
    maxPixels: 1e9
  }).get('precipitation' || 'precipitationCal');

  // Get pixel count for validation
  const cairnsCount = rainfallTotal.reduceRegion({
    reducer: ee.Reducer.count(),
    geometry: cairns.buffer(1000),
    scale: 1000,
    maxPixels: 1e9
  }).get('precipitation' || 'precipitationCal');

  const cooktownCount = rainfallTotal.reduceRegion({
    reducer: ee.Reducer.count(),
    geometry: cooktown.buffer(1000),
    scale: 1000,
    maxPixels: 1e9
  }).get('precipitation' || 'precipitationCal');

  const cairnsVal = await cairnsRain.getInfo();
  const cooktownVal = await cooktownRain.getInfo();
  const cairnsPix = await cairnsCount.getInfo();
  const cooktownPix = await cooktownCount.getInfo();

  print(`Cairns rainfall (mm): ${cairnsVal?.toFixed(2)}, Pixels: ${cairnsPix}`);
  print(`Cooktown rainfall (mm): ${cooktownVal?.toFixed(2)}, Pixels: ${cooktownPix}`);

  // 4. Validation & Final Answer
  if (cairnsPix === 0 || cooktownPix === 0) {
    print("No valid pixels at one or both locations");
    print("<answer>C2</answer>");
  } else if (cairnsVal === null || cooktownVal === null || 
             isNaN(cairnsVal) || isNaN(cooktownVal)) {
    print("Invalid rainfall values");
    print("<answer>C3</answer>");
  } else if (cairnsVal > cooktownVal) {
    print("Cairns received more rainfall");
    print("<answer>A</answer>");
  } else {
    print("Cairns did not receive more rainfall");
    print("<answer>B</answer>");
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
